   235          /* success */
   236          hash->alg_id = cbor_get_uint8(hash_item_alg_id);
   237          hash->value = g_byte_array_new();
   238          g_byte_array_append(hash->value,
   239                              cbor_bytestring_handle(hash_item_value),
   240                              cbor_bytestring_length(hash_item_value));
   241          g_ptr_array_add(payload->hashes, g_steal_pointer(&hash));
   242          return TRUE;
