   403  static gboolean
   404  fu_coswid_firmware_parse_entity(FuCoswidFirmware *self,
   405                                  cbor_item_t *item,
   406                                  gpointer user_data,
   407                                  GError **error)
   408  {
   409          FuCoswidFirmwarePrivate *priv = GET_PRIVATE(self);
   410          struct cbor_pair *pairs = cbor_map_handle(item);
   411          guint entity_role_cnt = 0;
   412          g_autoptr(FuCoswidFirmwareEntity) entity = g_new0(FuCoswidFirmwareEntity, 1);
   413
   414          for (gsize i = 0; i < cbor_map_size(item); i++) {
   415                  FuCoswidTag tag_id = cbor_get_uint8(pairs[i].key);
   416                  if (tag_id == FU_COSWID_TAG_ENTITY_NAME) {
   417                          entity->name = fu_coswid_firmware_strndup(pairs[i].value);
   418                  } else if (tag_id == FU_COSWID_TAG_REG_ID) {
   419                          entity->regid = fu_coswid_firmware_strndup(pairs[i].value);
   420                  } else if (tag_id == FU_COSWID_TAG_ROLE) {
   421                          if (cbor_isa_uint(pairs[i].value)) {
   422                                  FuCoswidEntityRole role = cbor_get_uint8(pairs[i].value);
   423                                  entity->roles[entity_role_cnt++] = role;
   424                          }
   425                          for (guint j = 0; j < cbor_array_size(pairs[i].value); j++) {
   426                                  g_autoptr(cbor_item_t) value = cbor_array_get(pairs[i].value, j);
   427                                  FuCoswidEntityRole role = cbor_get_uint8(value);
   428                                  if (entity_role_cnt >= G_N_ELEMENTS(entity->roles)) {
   429                                          g_set_error_literal(error,
   430                                                              FWUPD_ERROR,
   431                                                              FWUPD_ERROR_INVALID_DATA,
   432                                                              "too many roles");
   433                                          return FALSE;
   434                                  }
   435                                  entity->roles[entity_role_cnt++] = role;
   436                          }
   437                  } else {
   438                          g_debug("unhandled tag %s from %s",
   439                                  fu_coswid_tag_to_string(tag_id),
   440                                  fu_coswid_tag_to_string(FU_COSWID_TAG_ENTITY));
   441                  }
   442          }
   443
   444          /* success */
   445          g_ptr_array_add(priv->entities, g_steal_pointer(&entity));
   446          return TRUE;
   447  }
